pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Bound inputs to prevent excessive gas or out-of-bounds issues
        vm.assume(caddress != address(0) && caddress.code.length > 0); // ensure caddress is a contract
        // We'll attempt a call to transfer and catch if it reverts
        try c.transfer(from, caddress, _tos, v) returns (bool result) {
            // If it succeeded, then the internal call must have succeeded (i.e., _s == true)
            // For the reference C, this should always happen (no revert)
            assertTrue(result == true, "transfer should return true when it succeeds");
        } catch {
            // If it reverts, then the internal call must have failed (i.e., _s == false)
            // Note: the reference C only reverts if the internal call reverts.
            // Since we cannot directly observe the internal call result, we assert that
            // a revert is acceptable only if the internal call would have reverted.
            // However, the general rule is: for any input, the reference C either succeeds
            // (returns true) or reverts (if the internal call reverts). There's no other outcome.
            // We'll just assert that the revert is consistent (always possible).
            assertTrue(true, "revert is allowed when internal call fails");
        }
    }
}

